import{d as p,C as a,o as d,c as g,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十一章","description":"《正易心法》第三十一章——一岁之数三百六十，八卦八变气数已尽：乾宫八变复乾则天气尽，坤宫复坤则地气尽，八宫各八变，八八六十四数，天地雷风水火山泽之气无余蕴。","frontmatter":{"title":"正易心法·第三十一章","description":"《正易心法》第三十一章——一岁之数三百六十，八卦八变气数已尽：乾宫八变复乾则天气尽，坤宫复坤则地气尽，八宫各八变，八八六十四数，天地雷风水火山泽之气无余蕴。","category":"guide","aliases":["正易心法第三十一章","八卦八变气数已尽","八宫八变"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-31.md","filePath":"yijing/zheng-yi-xin-fa/chapter-31.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-31.md"},k=p({...c,setup(u){const i=[{id:"z31-01",label:"一、一岁之数",showLabel:!0,sentences:[["一岁之数，三百六十。八卦八变，",{text:"气数已尽",glossary:"qishuYijin"},"。"]],note:["一年的天数是三百六十。八卦各经八次变化，气数便完整走完。（**「尽」不是消亡，是循环完备**：从本卦出发，经七个变卦，第八变回到本卦——**一次完整的「出发→游历→归来」。**）"]},{id:"z31-02",label:"二、乾宫天气尽",showLabel:!0,sentences:[["乾、姤、遁、否、观、剥、晋、大有，八变而复乾，则天之气尽。"]],note:["乾、姤、遁、否、观、剥、晋、大有，经八变而回复为乾，则天的气数走完。（**乾宫八变正是第十九章所说的一卦八变**，两处完全一致。其中「晋」为游魂、「大有」为归魂——**魂离本宫再归本宫**，这才是八变的完整含义。）"]},{id:"z31-03",label:"三、坤宫地气尽",showLabel:!0,sentences:[["坤、复、临、泰、大壮、夬、需、比，八变而复坤，则地之气尽。"]],note:["（**坤宫前五卦正是十二消息卦的「阳长」序列**：复（一阳生）→ 临（二阳）→ 泰（三阳）→ 大壮（四阳）→ 夬（五阳）——从纯阴出发，逐爻变阳。后两卦「需」「比」则是游魂与归魂，与乾宫同例。**乾宫从纯阳往阴走，坤宫从纯阴往阳走——两宫正好是一对镜像。**）"]},{id:"z31-04",label:"四、震宫雷气尽",showLabel:!0,sentences:[["震、豫、解、恒、升、井、大过、随，八变而复震，则雷之气尽。"]],note:["（**震宫第七卦是大过**——大过是第十六章八个「对体卦」（翻转不变）之一，在此正是**游魂**之位。**这不是巧合：对体卦不随翻转而变，它们在变化序列里恰好落在「魂将离本宫」的那一位上。**）"]},{id:"z31-05",label:"五、艮宫山气尽",showLabel:!0,sentences:[["艮、贲、大畜、损、睽、履、中孚、渐，八变而复艮，则山之气尽。"]],note:["（**艮宫第七卦是中孚**，同为对体卦、同为游魂位；而中孚与震宫的大过互为错卦——**两卦分居两宫的同一位置，左右相对。**）"]},{id:"z31-06",label:"六、离宫火气尽",showLabel:!0,sentences:[["离、旅、鼎、未济、蒙、涣、讼、同人，八变而复离，则火之气尽。"]],note:["（**离宫有两卦值得留意**：第四卦「未济」是六十四卦的末卦，「事未完成」；末卦「同人」与乾宫的大有同属第十八章的「舜禹之卦」（文德嗣位），**分居离、乾两宫。**）"]},{id:"z31-07",label:"七、坎宫水气尽",showLabel:!0,sentences:[["坎、节、屯、既济、革、丰、明夷、师，八变而复坎，则水之气尽。"]],note:["坎、节、屯、既济、革、丰、明夷、师，经八变而回复为坎，则水的气数走完。（**此为底本所阙**：今见底本坎宫一行丢失，此据第三十九章「八宫卦法」（坎宫：坎、节、屯、既济、革、丰、明夷、师）补足，**以成八八六十四之数**。）"]},{id:"z31-08",label:"八、巽宫风气尽",showLabel:!0,sentences:[["巽、小畜、家人、益、无妄、噬嗑、颐、蛊，八变而复巽，则风之气尽。"]],note:["（**巽宫第七卦是颐**——八个对体卦之一，也是游魂位。**颐（形如口，实两端、虚中间）与兑宫的小过（形如飞鸟）遥相映照**，正应第十八章「一在未生（中孚）、一在已过（小过）」之辨。）"]},{id:"z31-09",label:"九、兑宫泽气尽",showLabel:!0,sentences:[["兑、困、萃、咸、蹇、谦、小过、归妹，八变而复兑，则泽之气尽。"]],note:["（**兑宫第七卦是小过**——八个对体卦的最后一个。**至此可见一个规律：八个对体卦中，乾、坤、坎、离是四宫的首卦（纯卦），而颐、大过、中孚、小过分别是巽、震、艮、兑四宫的游魂卦——八个对体卦，恰好布满八宫的「首」与「游魂」两个位置。**）"]},{id:"z31-10",label:"十、无余蕴",showLabel:!0,sentences:[["凡此八卦，各八变，八八六十四数，则天、地、雷、风、水、火、山、泽之气无",{text:"余蕴",glossary:"yuyun"},"矣。",{text:"是为一义",glossary:"shiweiYiyi"},"。"]],note:["凡此八卦，各经八变，八八共六十四数，则天、地、雷、风、水、火、山、泽的气，没有剩余、没有遗漏，全部走完。这是一层意思。（**「无余蕴」＝六十四卦覆盖了八类气的所有状态**；而「**是为一义**」四个字很重要——**它暗示这个结构还有其他层面的意思未展开。** 麻衣有一个持续的写作习惯：**点出有更深的东西，但不全部展开。**）"]}],o=[{id:"qishuYijin",term:"气数已尽",pinyin:"qì shù yǐ jìn",meaning:"这一类气的数量完整走完。尽＝完整、穷尽，不是消亡，是循环完备。"},{id:"yuyun",term:"余蕴",pinyin:"yú yùn",meaning:"剩余、积存、遗漏。无余蕴即八类气全部走完，无一遗漏。"},{id:"shiweiYiyi",term:"是为一义",pinyin:"shì wéi yī yì",meaning:"这是一层意思。暗示还有其他层意思未展开——麻衣「点到为止」的写法。"}];return(b,n)=>{const l=a("DaoTextReading"),r=a("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t("",21)),e(l,{colophon:"一岁三百六十 · 八宫八变 · 气数已尽 · 无余蕴",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十一章原文",sections:i,glossary:o}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入，唯底本乾宫阙「否」、且整阙坎宫一行，此据第十九章「一卦八变」与第三十九章「八宫卦法」补足（乾宫作「乾、姤、遁、否、观、剥、晋、大有」，坎宫作「坎、节、屯、既济、革、丰、明夷、师」），以成「八八六十四」之数。此系脱文，非麻衣之误。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"八变",pinyin:["bā","biàn"],meaning:"从本卦出发，经七个变卦，第八变复归本卦——一次完整的「出发→游历→归来」。"},{term:"气数已尽",pinyin:["qì","shù"],meaning:"这一类气的数量完整走完。尽＝完整、穷尽，不是消亡，是循环完备。"},{term:"无余蕴",pinyin:["wú","yú"],meaning:"没有剩余、没有遗漏。六十四卦覆盖八类气（天地雷风、水火、山泽）的所有状态。"},{term:"是为一义",pinyin:["shì","wéi"],meaning:"这是一层意思——暗示还有其他层意思未展开，是麻衣典型的「点到为止」。"},{term:"游魂与归魂",pinyin:["yóu","hún"],meaning:"七变中的第六变（上爻变）为游魂、第七变（四爻复变）为归魂。乾宫的晋与大有即此二卦。"}]}),n[3]||(n[3]=t("",23))])}}});export{m as __pageData,k as default};
